BEGIN;
ALTER TABLE public.ct_preferences ADD COLUMN language_selected boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.ct_language() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';END IF;RETURN jsonb_build_object('language',coalesce((SELECT language FROM public.ct_preferences WHERE user_id=auth.uid()),'fr'),'configured',coalesce((SELECT language_selected FROM public.ct_preferences WHERE user_id=auth.uid()),false));END $$;
CREATE OR REPLACE FUNCTION public.ct_set_language(p_language text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.ct_profiles WHERE id=auth.uid()) THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';END IF;IF p_language IS NULL OR p_language NOT IN('fr','en') THEN RAISE EXCEPTION 'Choose French or English';END IF;INSERT INTO public.ct_preferences(user_id,language,language_selected) VALUES(auth.uid(),p_language,true) ON CONFLICT(user_id) DO UPDATE SET language=EXCLUDED.language,language_selected=true,updated_at=now();END $$;
COMMIT;
